import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.B5WAEDB7.js";const o="/screenshots/en/erste-schritte/schnellstart/schritt-1-space-anlegen.png",i="/screenshots/en/erste-schritte/schnellstart/schritt-2-spaltentyp-waehlen.png",r="/screenshots/en/erste-schritte/schnellstart/schritt-2-grid-mit-feldern.png",f=JSON.parse('{"title":"Your first app in 15 minutes","description":"A complete walkthrough — from an empty table to an automatic confirmation email.","frontmatter":{"title":"Your first app in 15 minutes","description":"A complete walkthrough — from an empty table to an automatic confirmation email."},"headers":[],"relativePath":"en/erste-schritte/schnellstart.md","filePath":"en/erste-schritte/schnellstart.md","lastUpdated":1787319236000}'),l={name:"en/erste-schritte/schnellstart.md"};function d(c,e,h,p,u,m){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="your-first-app-in-15-minutes" tabindex="-1">Your first app in 15 minutes <a class="header-anchor" href="#your-first-app-in-15-minutes" aria-label="Permalink to &quot;Your first app in 15 minutes&quot;">​</a></h1><p>This guide builds a complete, small application: an <strong>event registration</strong>. By the end, people can register through a link, automatically receive a confirmation, and you can see the current state at a glance.</p><p>Along the way you&#39;ll touch all four building blocks of ApptiveGrid — Grid, Form, Flow, and Page.</p><hr><h2 id="_1-·-create-a-space-and-grid-2-minutes" tabindex="-1">1 · Create a Space and Grid (2 minutes) <a class="header-anchor" href="#_1-·-create-a-space-and-grid-2-minutes" aria-label="Permalink to &quot;1 · Create a Space and Grid (2 minutes)&quot;">​</a></h2><ol><li>In the overview, click <strong>Create new Space</strong> and name it <code>Events</code>.</li><li>Then create the first Grid: <code>Registrations</code>.</li></ol><p><img src="'+o+'" alt="The dialog for creating a Space, with the Create button highlighted"></p><p>→ <a href="/en/spaces/space-anlegen">Create a Space</a></p><h2 id="_2-·-create-fields-3-minutes" tabindex="-1">2 · Create fields (3 minutes) <a class="header-anchor" href="#_2-·-create-fields-3-minutes" aria-label="Permalink to &quot;2 · Create fields (3 minutes)&quot;">​</a></h2><p>Use the <strong>+</strong> at the right end of the column headers to create these fields:</p><table tabindex="0"><thead><tr><th>Column name</th><th>Column type</th></tr></thead><tbody><tr><td><code>Name</code></td><td>Text</td></tr><tr><td><code>Email</code></td><td>E-Mail</td></tr><tr><td><code>People</code></td><td>Number</td></tr><tr><td><code>Status</code></td><td>Single Select with the options <code>New</code>, <code>Confirmed</code>, <code>Cancelled</code></td></tr></tbody></table><p>You choose the type while creating the column:</p><p><img src="'+i+'" alt="Choosing the column type when creating a field"></p><p>The Grid then stands with its fields in place:</p><p><img src="'+r+`" alt="The Registrations grid with the Name, Email, and People fields"></p><div class="tip custom-block"><p class="custom-block-title">The type is the most important decision</p><p>An email field validates the input, a number field can be summed, a single select later becomes the columns of a Kanban board. Text can&#39;t do any of that.</p><p>→ <a href="/en/referenz/spaltentypen">Column types reference</a></p></div><h2 id="_3-·-create-a-form-3-minutes" tabindex="-1">3 · Create a Form (3 minutes) <a class="header-anchor" href="#_3-·-create-a-form-3-minutes" aria-label="Permalink to &quot;3 · Create a Form (3 minutes)&quot;">​</a></h2><ol><li>In the sidebar under the Grid, choose <strong>Create form</strong> and name it <code>Registration</code>.</li><li>Use <strong>Add fields</strong> to add the <code>Name</code>, <code>Email</code>, and <code>People</code> fields — <strong>not</strong> <code>Status</code>.</li><li>Set <code>Name</code> and <code>Email</code> to <strong>Required field</strong>.</li><li>On the <strong>Layout</strong> tab, enter a title, such as <code>Summer Party Registration</code>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Status doesn&#39;t belong on the form</p><p>Status is an internal value you assign — not the registering person. Anything the form doesn&#39;t ask for stays empty on submission.</p></div><p>→ <a href="/en/formulare/formular-erstellen">Create a form</a></p><h2 id="_4-·-share-the-form-1-minute" tabindex="-1">4 · Share the Form (1 minute) <a class="header-anchor" href="#_4-·-share-the-form-1-minute" aria-label="Permalink to &quot;4 · Share the Form (1 minute)&quot;">​</a></h2><ol><li>Click <strong>Create link</strong>.</li><li>Copy the link — or use the QR code.</li><li>Test the form yourself via <strong>Preview in new tab</strong>.</li></ol><div class="danger custom-block"><p class="custom-block-title">The link is public by default</p><p>Anyone with the link can fill out the form. For a summer party, that&#39;s exactly what you want. For internal or sensitive forms, set <strong>Configure restrictions</strong> first.</p><p>→ <a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></p></div><p>Submit the form once with your own address. The Entry appears in the Grid right away.</p><h2 id="_5-·-automate-the-confirmation-4-minutes" tabindex="-1">5 · Automate the confirmation (4 minutes) <a class="header-anchor" href="#_5-·-automate-the-confirmation-4-minutes" aria-label="Permalink to &quot;5 · Automate the confirmation (4 minutes)&quot;">​</a></h2><ol><li>In the sidebar, open <strong>Flows</strong> and click <strong>Create flow</strong>. Name it <code>Send confirmation</code>.</li><li>On the <strong>Trigger</strong> tab, choose <strong>Entry via form</strong>, then pick the Grid and Form.</li><li>On the <strong>Actions</strong> tab, choose <strong>Email</strong> and connect it to the trigger.</li><li>Configure the email: <ul><li><strong>To</strong>: use <em>Use values from previous steps</em> to pick the <code>Email</code> field</li><li><strong>Subject</strong>: <code>Your registration has arrived</code></li><li><strong>Content</strong>: fixed text, with the <code>Name</code> field inserted</li></ul></li></ol><div class="danger custom-block"><p class="custom-block-title">Test before going live</p><p>Use <strong>Test flow</strong> — the step uses the last row of the Grid, which is your own test entry.</p><p>A test run is <strong>not a dry run</strong>: the email really goes out. That&#39;s why using your own address as the test entry matters.</p></div><p>Check the <strong>History</strong> tab to confirm the run has the status <em>Done</em>.</p><p>→ <a href="/en/flows/ersten-flow-bauen">Build your first flow</a></p><h2 id="_6-·-get-an-overview-2-minutes" tabindex="-1">6 · Get an overview (2 minutes) <a class="header-anchor" href="#_6-·-get-an-overview-2-minutes" aria-label="Permalink to &quot;6 · Get an overview (2 minutes)&quot;">​</a></h2><p>Add two more <a href="/en/ansichten/was-ist-eine-ansicht">Views</a> on the same Grid:</p><p><strong>Kanban by status</strong> — shows registrations as cards in the columns <code>New</code>, <code>Confirmed</code>, <code>Cancelled</code>. Cards can be moved by drag and drop.</p><p><strong>&quot;Open&quot; table</strong> — a Grid View with the filter <code>Status</code> <code>equals</code> <code>New</code>.</p><div class="tip custom-block"><p class="custom-block-title">All Views show the same data</p><p>You&#39;re not creating copies. Change an Entry in the Kanban board, and the change is immediately visible everywhere.</p></div><p>In the table, use the summary row to show the <strong>Sum</strong> of the <code>People</code> column — now you know at a glance how many people are coming.</p><hr><h2 id="what-you-have-now" tabindex="-1">What you have now <a class="header-anchor" href="#what-you-have-now" aria-label="Permalink to &quot;What you have now&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Space &quot;Events&quot;</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Grid &quot;Registrations&quot;</span></span>
<span class="line"><span>│   ├── View &quot;All registrations&quot;    (Table)</span></span>
<span class="line"><span>│   ├── View &quot;Open&quot;                 (Table, filtered)</span></span>
<span class="line"><span>│   ├── View &quot;By status&quot;            (Kanban)</span></span>
<span class="line"><span>│   └── Form &quot;Registration&quot;         → shared publicly</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Flow &quot;Send confirmation&quot;</span></span>
<span class="line"><span>    ├── Trigger: Entry via form</span></span>
<span class="line"><span>    └── Action:  Email</span></span></code></pre></div><p>A working application: capture, automation, and an overview.</p><h2 id="natural-next-steps" tabindex="-1">Natural next steps <a class="header-anchor" href="#natural-next-steps" aria-label="Permalink to &quot;Natural next steps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Path</th></tr></thead><tbody><tr><td>Link registrations to a person</td><td>Second Grid <code>Events</code>, <a href="/en/grids/verknuepfungen">linked</a></td></tr><tr><td>Publish an attendee list</td><td><a href="/en/seiten/auswertungen">Page with an embedded View</a></td></tr><tr><td>Bring colleagues on board</td><td><a href="/en/zusammenarbeit/personen-einladen">Invite people</a></td></tr><tr><td>Handle cancellations automatically</td><td>Flow with trigger <em>Entry was updated</em></td></tr><tr><td>Confirm only after review</td><td><a href="/en/flows/seiten-in-flows">Pages in flows</a></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/erste-schritte/was-ist-apptivegrid">What is ApptiveGrid</a> — the terms in context</li><li><a href="/en/erste-schritte/oberflaeche">The interface at a glance</a></li><li><a href="/en/erste-schritte/vorlagen">Start with a template</a></li></ul>`,43)])])}const b=t(l,[["render",d]]);export{f as __pageData,b as default};
